head.script:
scwin.btnSearch_onclick = function() {
    if (inpSearchYymm.getValue() == "") {
        alert("적용년월을 입력 후 조회하세요.");
        inpSearchYymm.focus();
        return;
    }
    //$w.executeSubmission( "getDataList01" );
    comLib.execute("getDataList01", {
        "srvcCd": "tklife.MM.TKLMM320.GetComiRateList"
    });
};
scwin.btnPlus_onclick = function() {
    if (grid01.getFocusedRowIndex() < 0) {
        alert("추가할 row를 선택하세요.");
    } else {
        var row = grid01.getFocusedRowIndex();
        var data = dataList01.getRowJSON(row);
        dataList01.insertRow(row + 1);
        data.SEQ = "", data.CALC_STR_CNT = "", data.CALC_END_CNT = "", data.CALC_TYPE_CD = "", data.CALC_RATE = "";
        dataList01.setRowJSON(row + 1, data, true);
        data = null;
    }
};
scwin.btnExcelUpload_onclick = function() {
    try {
        dataList01.removeAll();
        var options = {};
        options.type = "1";
        //options.removeColumns = "DEL_GB";
        grid01.advancedExcelUpload(options);
        //comLib.excelUpload("grid01");
    } catch (e) {
        console.log(e);
    }
};
scwin.btnExcelDown_onclick = function() {
    var options = {};
    /*
    options.fileName = "download("+inpSearchYymm.getValue()+").xls"; 
    options.type  = "1"; 
    options.startRowIndex = 0;
    options.startColumnIndex = 0; 
    var infoArr = [];
    grid01.advancedExcelDownload(options , infoArr);


    */
    comLib.excelDownload("grid01", "download(" + inpSearchYymm.getValue() + ").xls", options);
};
scwin.btnSave_onclick = function() {
    var isvalid = gaUtil.validCheck(grid01, ["CALC_STR_CNT", "CALC_END_CNT", "CALC_TYPE_CD", "CALC_RATE", "APP_STR_DATE", "APP_END_DATE"]);
    if (isvalid) {
        //$w.executeSubmission( "saveDataList01" );
        comLib.execute("saveDataList01", {
            "srvcCd": "tklife.MM.TKLMM320.SaveComiRate",
            "callback": "scwin.saveDataList01_submitdone"
        });
    }
};
scwin.saveDataList01_submitdone = function(e) {
    alert("저장에 성공하였습니다.");
    //$w.executeSubmission( "getDataList01" );
    comLib.execute("getDataList01", {
        "srvcCd": "tklife.MM.TKLMM320.GetComiRateList"
    });
};
scwin.dataList01_oncelldatachange = function(info) {
    mmUtil.chkAppDate(grid01);
};
scwin.btnSearchDepcd_onclick = function() {
    tklmm.popup.grid = {
        id: "",
        row: "",
        col: ""
    };
    tklmm.searchPopupDept();
};
scwin.btnSearchProdCd_onclick = function() {
    tklmm.popup.grid = {
        id: "",
        row: "",
        col: ""
    };
    tklmm.searchPopupProd();
};
scwin.onpageload = function() {
    window.tklmm = {};
    tklmm.popup = {};
    tklmm.popup.grid = {
        id: "",
        row: "",
        col: ""
    };
    window.comLib = {};
    /**
     * 엑셀 업로드
     * 
     * @param[jsonObj]
     *    type          : [defalut: 1] 1이면 엑셀 파일이 그리드의 보이는 결과로 만들어져있을때 0이면 엑셀 파일이 그리드의 실제 데이터로 구성되어있을때
     *    sheetNo       : [defalut: 0] excel파일에서 그리드의 데이터가 있는 sheet번호
     *    startRowIndex : [defalut: 3] excel파일에서 그리드의 데이터가 시작되는 행의 번호(헤더 포함)
     *    startColumnIndex: [defalut: 0] excel파일에서 그리드의 데이터가 시작되는 열의 번호
     *    endColumnIndex : [defalut: 0] excel파일에서 그리드의 데이터가 끝나는 열의 index (엑셀컬럼수가 그리드컬럼수 보다 작은 경우 그리드 컬럼수를 설정)
     *    headerExist   : [defalut: 1] excel파일에서 그리드의 데이터에 header가 있는지 여부(1이면 header 존재 0이면 없음)
     *    footerExist   : [defalut: 0] excel파일에서 그리드의 데이터에 footer가 있는지 여부(1이면 footer 존재 0이면 없음 기본값은 1 그리드에 footer가 없으면 적용되지 않음)
     *    append        : [defalut: 0] excel파일에서 가져온 데이터를 그리드에 append시킬지 여부(1이면 현재 그리드에 데이터를 추가로 넣어줌 0이면 현재 그리드의 데이터를 삭제하고 넣음)
     *    hidden        : [defalut: 0] 읽어들이려는 엑셀파일에 hidden column이 저장되어 있는지 여부를 설정하는 int형 숫자
     *                    (0이면 엑셀파일에 hidden 데이터가 없으므로 그리드 hidden column에 빈 데이터를 삽입
     *                     1이면 엑셀파일에 hidden 데이터가 있으므로 엑셀 파일로부터 hidden 데이터를 삽입 )
     *    status        : [defalut: C]업로드된 데이터의 초기 상태값, 설정하지 않으면 "R"로 설정되며 "C"값을 설정 할 수 있다.
     *    removeColumns : upload시 excel에 data가 포함되어 있지 않은 컬럼목록으로 기본으로 제외되는 inputType이 아닌 컬럼 목록을 나열한다.
     *                    (,로 구분) ex)"user_id,user_type"
     */
    comLib.excelUpload = function(gridId, options) {
        window.grdObj = $w.comp[gridId];
        // 기본 제외 컬럼 정의
        window._insertColumns = new Array();
        if (typeof options == "undefined")
            options = {};
        window.headerObj = grdObj.getHeaderHtmlInfo().rowArr;
        options.type = options.type ? options.type : "1";
        options.sheetNo = options.sheetNo ? options.sheetNo : "0";
        options.startRowIndex = options.startRowIndex ? options.startRowIndex : "3";
        options.startColumnIndex = options.startColumnIndex ? options.startColumnIndex : "0";
        options.headerExist = options.headerExist ? options.headerExist : "1";
        options.footerExist = options.footerExist ? options.footerExist : "0";
        options.append = options.append ? options.append : "0";
        options.hidden = options.hidden ? options.hidden : "0";
        options.status = options.status ? options.status : "C";
        window.iLen = grdObj.getTotalCol();
        for (window.idx = 0; idx < iLen; idx++) {
            if ($.inArray(grdObj.getColumnType(idx), comLib.consts.EXCEL_EXCLUDE_INPUT_TYPE) != -1) {
                _insertColumns.push({
                    "columnIndex": idx,
                    "columnValue": ""
                });
            }
            // 화면에는 보여지나 엑셀에서는 빠질 컬럼
            if (typeof headerObj[0][idx] != 'undefined' && typeof headerObj[0][idx].nonExcel != 'undefined' && headerObj[0][idx].nonExcel) {
                if ($.inArray(idx, _insertColumns) != -1)
                    continue;
                _insertColumns.push({
                    "columnIndex": idx,
                    "columnValue": ""
                });
            }
        }
        // UI 에서 정의한 제외 컬럼
        if (options.removeColumns) {
            window.removeColumn = options.removeColumns.split(",");
            for (window.idx = 0; idx < removeColumn.length; idx++) {
                window._columnIndex = grdObj.getColumnIndex(removeColumn[idx]);
                if ($.inArray(_columnIndex, _insertColumns) != -1)
                    continue;
                _insertColumns.push({
                    "columnIndex": _columnIndex,
                    "columnValue": ""
                });
            }
        }
        delete options.removeColumns;
        options.insertColumns = _insertColumns;
        grdObj.advancedExcelUpload(options);
    };
    //화면 로드 
    tklmm.init = function() {
        /*		
        		//공통 코드값 가져오기
        		gaUtil.commCodeSet([{
        			"cd":"COMI_TYPE_CD"
        			,"refAlph":"Y"
        			,"comp":"inpSearchComiTypeCd,grid.grid01.COMI_TYPE_CD"
        		},{
        			"cd":"CUSTTYPE"
        			,"refAlph":"Y"
        			,"comp":"grid.grid01.CUST_TYPE,inpSearchCustType"
        		},{
        			"cd":"PYMTCY"
        			,"useYn":"Y"
        			,"comp":"grid.grid01.PYMT_CYCLE,inpSearchPymtCycle"
        		},{
        			"cd":"PYMTTERM"
        			,"name":"CD"
        			,"useYn":"Y"
        			,"comp":"grid.grid01.PYMT_TERM,inpSearchPymtTerm"
        		},{
        			"cd":"CALC_TYPE_CD"
        			,"useYn":"Y"
        			,"comp":"grid.grid01.CALC_TYPE_CD"
        		},{
        			"sendUrl":"Tklmm212OT.GetDepList"
        			,"code":"DEPCD"
        			,"name":"DEPNM"
        			,"cd":"depList"
        			,"rCd":"dl_tklmm301"
        			,"comp":"grid.grid01.DEPCD"

        		},{
        			"sendUrl":"tklife.MM.Tklmm311OT.getProdList"
        			,"code":"PROD_MAIN_CD"
        			,"name":"S_PROD_NM"
        			,"cd":"getProdList"
        			,"rCd":"dataList01"
        			,"comp":"grid.grid01.PROD_CD"

        		} ]);	
        */
        inpSearchYymm.setValue(WebSquare.date.getFormattedDate(new Date(), "yyyyMM"));
        //scwin.btnSearch_onclick();
        grid01.setColumnNodeSet("DEPCD", "data:dc_Tklmm212OTGetDepList", "DEPNM", "DEPCD");
    };
    //검색 버튼 click
    //추가 버튼 click
    //엑셀 upload click
    //엑셀 download click
    //저장 버튼 click
    //저장 submit done
    /***********************************************************/
    // 검색 조건 POPUP 
    // 부서(대리점) popup return
    tklmm.searchPopupDept = function() {
        openPopup("/ga/app/mm/TKLMM212.xml", "POPUPWIN", {
            width: 1023,
            resize: false
        }, {
            PRAM_CNT: '2',
            V_QRY1: WebSquare.text.BASE64URLEncoder(inpSearchDepNm.getValue()) // 검색조건에 넣을 파라미터    
                ,
            R_NAME1: 'inpSearchDepNm' // 반환된 값을 출력할 객체이름
                ,
            R_NAME2: 'inpSearchDepCd',
            C_NAME1: 'inpSearchDepNm' // 반환시 값을 클리어할 객체이름
                ,
            C_NAME2: 'inpSearchDepCd',
            FN_SET_VALUE: 'W' // 반환시 값 할당 함수구분 W:웹스퀘어 setValue H: HTML value
                ,
            AUTO_SEARCH: 'N' // 자동검색여부
                ,
            AFTER_FUNC_NAME: "tklmm.getReturnDept"
        });
    };
    tklmm.searchPopupProd = function() {
        openPopup("/ga/app/mm/TKLMM311.xml", "POPUPWIN", {
            width: 1023,
            resize: false
        }, {
            PRAM_CNT: '2',
            V_QRY1: WebSquare.text.BASE64URLEncoder(inpSearchProdNm.getValue()) // 검색조건에 넣을 파라미터    
                ,
            R_NAME1: 'inpSearchProdNm' // 반환된 값을 출력할 객체이름
                ,
            R_NAME2: 'inpSearchProdCd',
            C_NAME1: 'inpSearchProdNm' // 반환시 값을 클리어할 객체이름
                ,
            C_NAME2: 'inpSearchProdCd',
            FN_SET_VALUE: 'W' // 반환시 값 할당 함수구분 W:웹스퀘어 setValue H: HTML value
                ,
            AUTO_SEARCH: 'Y' // 자동검색여부
                ,
            AFTER_FUNC_NAME: "tklmm.getReturnProd"
        });
    };
    tklmm.getReturnDept = function(p) {
        if (tklmm.popup.grid.row) {
            dataList01.setCellData(tklmm.popup.grid.row, "DEPCD", p.DEPCD);
            dataList01.setCellData(tklmm.popup.grid.row, "DEPNM", p.DEPNM);
        } else {
            inpSearchDepcd.setValue(p.DEPCD);
            inpSearchDepNm.setValue(p.DEPNM);
        }
    };
    tklmm.getReturnProd = function(p) {
        if (tklmm.popup.grid.row) {
            dataList01.setCellData(tklmm.popup.grid.row, "PROD_CD", p.PROD_MAIN_CD);
            dataList01.setCellData(tklmm.popup.grid.row, "PROD_NM", p.S_PROD_NM);
        } else {
            inpSearchProdCd.setValue(p.PROD_MAIN_CD);
            inpSearchProdNm.setValue(p.S_PROD_NM + "-" + p.S_PROD_DNM);
        }
    };
    /***********************************************************/
    tklmm.init();

}
